    byte[] ivBytes = new byte[16];
    byte[] tag = new byte[16];
    byte[] aad = new byte[r.nextInt() % 1000 + 1000];
    r.nextBytes(keyBytes);
    r.nextBytes(input);
    r.nextBytes(ivBytes);
    r.nextBytes(aad);
    try {
